package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SchedRec struct { // 01 SCHED-REC, 16 bytes
	ScAcct  string          // PIC X(4) @0 len=4
	ScPrin  decimal.Decimal // PIC 9(5)V99 @4 len=7
	ScRate  decimal.Decimal // PIC 9(2)V99 @11 len=4
	ScYears int64            // PIC 9(1) @15 len=1
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string          // PIC X len=1 = "N"
var WsBal decimal.Decimal     // PIC 9(8)V99 len=10 = 0
var WsYear int64              // PIC 99 len=2 = 0
var WsCount int64             // PIC 99 len=2 = 0
var WsBalEd string            // PIC ZZ,ZZZ,ZZ9.99 len=13

var schedRec SchedRec

// file handling
var schedLines []string
var schedIdx int
var schedFile *os.File

func padRight(s string, n int) string {
	if len(s) >= n {
		if len(s) > n {
			return s[:n]
		}
		return s
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parsePic9Only(digits string, scale int32) decimal.Decimal {
	// digits is all numeric characters (maybe with spaces which should be 0?)
	// COBOL numeric DISPLAY: digits only, implied decimal
	s := strings.TrimSpace(digits)
	if s == "" {
		s = "0"
	}
	// keep only 0-9, if spaces inside treat as 0? but spec says digits
	// already filtered; if contains non-digit, treat as 0
	filtered := ""
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			filtered += string(ch)
		}
	}
	if filtered == "" {
		filtered = "0"
	}
	n, _ := decimal.NewFromString(filtered)
	// n is integer of digits, shift -scale
	return n.Shift(-scale)
}

func parseSchedLine(line string) SchedRec {
	// pad to 16
	if len(line) < 16 {
		line = line + strings.Repeat(" ", 16-len(line))
	}
	if len(line) > 16 {
		line = line[:16]
	}
	var r SchedRec
	r.ScAcct = line[0:4]
	r.ScPrin = parsePic9Only(line[4:11], 2)
	r.ScRate = parsePic9Only(line[11:15], 2)
	// years 1 digit
	c := line[15:16]
	if c[0] >= '0' && c[0] <= '9' {
		r.ScYears = int64(c[0] - '0')
	} else if strings.TrimSpace(c) == "" {
		r.ScYears = 0
	} else {
		r.ScYears = 0
	}
	return r
}

func storeWsBal(v decimal.Decimal) decimal.Decimal {
	// PIC 9(8)V99 : scale 2, integer 8 digits, total 10 digits kept low order
	// truncate toward zero to scale 2 (but caller already rounded appropriately)
	// then drop high order digits
	truncated := v.Truncate(2)
	// get scaled integer (value *100)
	scaled := truncated.Shift(2).Truncate(0)
	sign := scaled.Sign()
	absScaled := scaled.Abs()
	modBase := decimal.NewFromInt(10000000000) // 10^10
	// low order 10 digits
	moded := absScaled.Mod(modBase)
	if sign < 0 {
		moded = moded.Neg()
	}
	return moded.Shift(-2)
}

func formatWsBalEd(v decimal.Decimal) string {
	// picture ZZ,ZZZ,ZZ9.99 len 13
	// v is already stored value with scale 2 (maybe negative)
	neg := v.Sign() < 0
	absV := v.Abs()
	// high order truncation already applied; but do again for formatting drop?
	// Format spec says if value has more integer digits than picture, high order dropped.
	// Our WsBal already truncated to 8 integer digits, so ok. But to be safe apply same low order logic.
	// Use integerDigits=8, scale 2
	// Ensure truncated to 2
	absV = absV.Truncate(2)
	// separate int and frac
	// integer part: floor
	intPart := absV.Truncate(0)
	// fractional part: (absV - intPart) *100
	fracPart := absV.Sub(intPart).Shift(2).Truncate(0).Abs()
	// handle rounding edge where frac 100? Already truncated so not.
	// Low order integer digits: intPart mod 10^8
	intMod := intPart.Mod(decimal.NewFromInt(100000000))
	intInt := intMod.IntPart()
	fracInt := fracPart.IntPart()
	// if fracInt negative? not.
	if fracInt < 0 {
		fracInt = -fracInt
	}
	// Build intStr 8 digits zero padded
	intStr := fmt.Sprintf("%08d", intInt)
	decStr := fmt.Sprintf("%02d", fracInt)

	edited := []rune("ZZ,ZZZ,ZZ9.99") // len 13
	// placeholder positions for integer digits in order
	intPlace := []int{0, 1, 3, 4, 5, 7, 8, 9}
	// fill integer digits
	for i, pos := range intPlace {
		edited[pos] = rune(intStr[i])
	}
	// fill fractional digits (pos 11,12)
	edited[11] = rune(decStr[0])
	edited[12] = rune(decStr[1])

	// Z suppression
	suppressed := true
	for _, pos := range intPlace {
		// determine if this position is Z in original picture
		origIsZ := false
		// original picture chars: ZZ,ZZZ,ZZ9.99
		origPic := "ZZ,ZZZ,ZZ9.99"
		if origPic[pos] == 'Z' {
			origIsZ = true
		}
		if origIsZ {
			if suppressed && edited[pos] == '0' {
				edited[pos] = ' '
			} else {
				suppressed = false
			}
		} else { // '9' placeholder
			// '9' never becomes space, but don't affect suppression for comma decision? However
			// for suppression tracking, if we encounter '9' we do not change suppressed flag used for Z's?
			// We have already handled Z flag; for 9 we leave suppressed as is (so commas after Z's still suppressed)
			// But do not set to false on zero '9' (integer zero case)
			// If 9 digit is non-zero, should we consider that suppression ends for future Z? There is no Z after 9 in integer part, so irrelevant.
			// Keep suppressed unchanged.
		}
	}
	// comma handling: comma becomes space if all integer placeholders to its left are spaces
	commaPositions := []int{2, 6}
	for _, cpos := range commaPositions {
		allSpaces := true
		for _, p := range intPlace {
			if p < cpos {
				if edited[p] != ' ' {
					allSpaces = false
					break
				}
			}
		}
		if allSpaces {
			edited[cpos] = ' '
		} else {
			edited[cpos] = ','
		}
	}
	// decimal point remains '.'
	// handle negative: if negative, need sign? Picture has no sign, but if negative, COBOL would put sign?
	// For this program values are positive; ignore.
	_ = neg
	return string(edited)
}

func formatPIC99(v int64) string {
	// PIC 99 zero-padded to 2 digits, high order truncated
	// keep low order 2 digits
	abs := v
	if abs < 0 {
		abs = -abs
	}
	abs = abs % 100
	return fmt.Sprintf("%02d", abs)
}

func MAINPARA() {
	schedFile, _ = os.Open("input.dat")
	if schedFile != nil {
		scanner := bufio.NewScanner(schedFile)
		// allow long lines
		// Use default split (lines)
		for scanner.Scan() {
			line := scanner.Text()
			// Scanner strips newline, but retains other chars except \r?
			// Need to handle possible \r
			line = strings.TrimSuffix(line, "\r")
			schedLines = append(schedLines, line)
		}
		schedFile.Close()
	}
	// The COBOL OPEN INPUT will succeed even if file missing -> empty
	schedIdx = 0
	WsEofFlag = "N"
	WsBal = decimal.NewFromInt(0)
	WsYear = 0
	WsCount = 0
	WsBalEd = padRight("", 13)

	READPARA()
	for WsEofFlag != "Y" {
		PROCESSPARA()
	}
	// CLOSE already done (file closed)
	// DISPLAY "SCHEDULES: " WS-COUNT
	// WS-COUNT is PIC 99 -> zero padded 2
	// According to spec, DISPLAY numeric fields concatenated followed by newline
	// Need to format WS-COUNT as 2-digit zero padded
	fmt.Printf("SCHEDULES: %s\n", formatPIC99(WsCount))
}

func READPARA() {
	if schedIdx >= len(schedLines) {
		WsEofFlag = "Y"
		return
	}
	line := schedLines[schedIdx]
	schedIdx++
	schedRec = parseSchedLine(line)
	WsEofFlag = "N"
}

func PROCESSPARA() {
	// MOVE SC-PRIN TO WS-BAL
	WsBal = storeWsBal(schedRec.ScPrin)
	// PERFORM VARYING WS-YEAR FROM 1 BY 1 UNTIL WS-YEAR > SC-YEARS
	WsYear = 1
	for !(WsYear > schedRec.ScYears) {
		// COMPUTE WS-BAL ROUNDED = WS-BAL * (1 + SC-RATE / 100)
		factor := decimal.NewFromInt(1).Add(schedRec.ScRate.Shift(-2))
		product := WsBal.Mul(factor)
		rounded := product.Round(2) // half away from zero
		WsBal = storeWsBal(rounded)
		WsBalEd = formatWsBalEd(WsBal)
		// DISPLAY SC-ACCT " Y" WS-YEAR " " WS-BAL-ED
		fmt.Printf("%s Y%s %s\n", schedRec.ScAcct, formatPIC99(WsYear), WsBalEd)
		WsYear++
	}
	WsBalEd = formatWsBalEd(WsBal)
	fmt.Printf("%s FINAL %s\n", schedRec.ScAcct, WsBalEd)
	WsCount++
	READPARA()
}

func main() {
	MAINPARA()
}
